    'ชนิดงานกำหนดเองมีสถานะของตัวเอง (เช่น ใหม่ → กำลังทำ → เสร็จ) สถานะที่ “นับว่าเสร็จ” จะติ๊กงานเสร็จให้ จัดกลุ่ม กรอง และทำคอลัมน์บอร์ดตามสถานะได้': 'Custom task types have their own statuses (e.g. New → In progress → Done). A status that “counts as complete” completes the task. Group, filter and build board columns by status.',
    'ยังไม่มีชนิดงานกำหนดเอง': 'No custom task types yet', 'ชนิดเริ่มต้นของงานใหม่ (“+ เพิ่มงาน” ทุกทาง ฟอร์ม)': 'Default type for new tasks (every “+ Add task”, forms)',
